#include <iostream>
#include <random>
#include <vector>

void probar(int cantidad, int primer_lote) {
    std::mt19937 primero{53};
    std::mt19937 segundo{53};
    std::uniform_int_distribution<int> a{1, 9};
    std::uniform_int_distribution<int> b{1, 9};
    std::vector<int> completa;
    std::vector<int> lotes;
    for (int i{0}; i < cantidad; ++i) {
        completa.push_back(a(primero));
    }
    for (int i{0}; i < primer_lote; ++i) {
        lotes.push_back(b(segundo));
    }
    for (int i{0}; i < cantidad-primer_lote; ++i) {
        lotes.push_back(b(segundo));
    }
    std::cout << "Por lotes:" << (completa == lotes) << '\n';
    primero.seed(53);
    a.reset();
    std::vector<int> repetida;
    for (int i{0}; i < cantidad; ++i) {
        repetida.push_back(a(primero));
    }
    std::cout << "Reinicio:" << (completa == repetida) << "\n";
}

int main() {
    probar(6,2);
    probar(0,0);
    probar(1,0);
    probar(1,1);
    return 0;
}

