#include <iostream>
#include <random>
#include <vector>

int suma(const std::vector<int>& datos) {
    int total=0;
    for (int dato:datos) { total+=dato; }
    return total;
}

int main() {
    std::mt19937 motor{67};
    std::uniform_int_distribution<int> elegir{2,2};
    std::vector<int> primera;
    std::vector<int> continuacion;
    for (int i=0;i<3;++i) { primera.push_back(elegir(motor)); }
    for (int i=0;i<2;++i) { continuacion.push_back(elegir(motor)); }
    motor.seed(67);
    elegir.reset();
    std::vector<int> repetida;
    for (int i=0;i<3;++i) { repetida.push_back(elegir(motor)); }
    std::cout<<"Primero:"<<suma(primera)<<"\nContinuacion:"<<suma(continuacion)
             <<"\nRepeticion:"<<(primera==repetida)<<"\n";
    return 0;
}
